INSERT INTO `blog_posts` (`id`,`title`,`slug`,`category`,`gender`,`image`,`excerpt`,`content`,`content_format`,`tags`,`meta_title`,`meta_description`,`status`,`published_date`,`created_at`) VALUES ('21','QA TEST Sanitiser Article Men','qa-test-sanitiser-article-men','Style Guide','men','lookbook_4.png','QA sanitiser probe article for menswear.','<h2>QA Heading Two</h2>\n<p>Ordinary paragraph with <strong>bold</strong>, <em>italic</em> and <strong>legacy bold</strong>.</p>\n<ul><li>QA list item one</li><li>QA list item two</li></ul>\n<ol><li>QA ordered one</li></ol>\n<blockquote>QA quoted line</blockquote>\n<p><a href=\"https://example.com/qa\" target=\"_blank\" rel=\"noopener noreferrer\">QA external link</a> and <a href=\"/shop\">QA internal link</a></p>\n<p><a>QA javascript link</a></p>\n<p><a>QA obfuscated javascript link</a></p>\n<p><a>QA protocol-relative link</a></p>\n\n\n<p>QA paragraph with handlers</p>\n\n\n\n\n<p>QA div line one</p>\n<h3>QA heading four demoted</h3>\n<p>Plain text tail: sizes &lt; 40 are fine.</p>','html','qa','QA TEST Sanitiser','QA','Published','2026-08-09','2026-08-10 00:21:42');
INSERT INTO `blog_posts` (`id`,`title`,`slug`,`category`,`gender`,`image`,`excerpt`,`content`,`content_format`,`tags`,`meta_title`,`meta_description`,`status`,`published_date`,`created_at`) VALUES ('22','QA TEST No Cover Image Women','qa-test-no-cover-image-women','Style Guide','women','','QA article deliberately saved with no cover image.','QA plain text with anything under <a lakh is a steal.\n\n## QA Heading\n\nTail line.','text','qa','','','Published','2026-08-09','2026-08-10 00:21:42');
